// Diğer diller için yer tutucu (İngilizce içeriği kopyalar)
// Bu sayede dropdown menüde görünürler ve seçilebilirler.
// List of all supported codes from getLanguageLabel excluding default ones (tr, en, de, cn)
// Helper to create translations based on English with overrides
const createTranslation = (overrides) => {
    const base = JSON.parse(JSON.stringify(translations.en));
    if (!overrides) return base;
    
    for (const key in overrides) {
        if (typeof overrides[key] === 'object' && overrides[key] !== null && !Array.isArray(overrides[key])) {
             Object.assign(base[key], overrides[key]);
        } else {
             base[key] = overrides[key];
        }
    }
    return base;
};

