        'PT': 'pt', 'BR': 'pt', 'AO': 'pt', 'MZ': 'pt',
        'IR': 'fa', 'AF': 'fa',
        'IN': 'hi',
        'NP': 'ne',
        'AM': 'hy',
        'GR': 'el', 'CY': 'el',
        'RO': 'ro', 'MD': 'ro',
