// Not: IP tabanlı dil tespiti (get.geojs.io) gizlilik nedeniyle kaldırıldı.
// Dil seçimi: localStorage'daki kayıtlı tercih > tarayıcı dili > 'tr'.

// Dil koduna göre buton etiketi döndür
function getLanguageLabel(langCode) {
    const languageLabels = {
        'tr': 'TR', 'en': 'EN', 'de': 'DE', 'cn': 'CN',
        'es': 'ES', 'it': 'IT', 'pt': 'PT', 'fa': 'FA', 'hi': 'HI', 'ne': 'NE',
        'hy': 'HY', 'el': 'EL', 'ro': 'RO', 'id': 'ID', 'tl': 'TL', 'ja': 'JA',
        'ko': 'KO', 'ru': 'RU', 'ar': 'AR', 'bn': 'BN', 'fr': 'FR', 'my': 'MY',
        'th': 'TH', 'uz': 'UZ', 'dz': 'DZ', 'tg': 'TG', 'ky': 'KY', 'bg': 'BG',
        'he': 'HE', 'sl': 'SL', 'sq': 'SQ', 'ka': 'KA', 'ur': 'UR'
    };
    return languageLabels[langCode] || langCode.toUpperCase();
}

function getLanguageNativeName(langCode) {
    const nativeNames = {
        'tr': 'Türkçe', 'en': 'English', 'de': 'Deutsch', 'cn': '中文',
        'es': 'Español', 'it': 'Italiano', 'pt': 'Português', 'fa': 'فارسی',
        'hi': 'हिन्दी', 'ne': 'नेपाली', 'hy': 'Հայերեն', 'el': 'Ελληνικά',
        'ro': 'Română', 'id': 'Bahasa Indonesia', 'tl': 'Tagalog', 'ja': '日本語',
        'ko': '한국어', 'ru': 'Русский', 'ar': 'العربية', 'bn': 'বাংলা',
        'fr': 'Français', 'my': 'မြန်မာ', 'th': 'ไทย', 'uz': 'Oʻzbekcha',
        'dz': 'རྫོང་ཁ', 'tg': 'Тоҷикӣ', 'ky': 'Кыргызча', 'bg': 'Български',
        'he': 'עברית', 'sl': 'Slovenščina', 'sq': 'Shqip', 'ka': 'ქართული',
        'ur': 'اردو'
    };
    return nativeNames[langCode] || langCode.toUpperCase();
}

// Seçilen dil için butonun var olduğundan emin ol, yoksa ekle
function ensureLanguageButtonExists(lang) {
    if (FIXED_LANGUAGES.includes(lang)) return;

    const languageSwitchers = document.querySelectorAll('.language-switcher');
    const globalBtnMore = document.getElementById('btnMoreLanguages');

    languageSwitchers.forEach(switcher => {
        let existingBtn = null;
        switcher.querySelectorAll(`button[data-lang="${lang}"]`).forEach(btn => {
            if (!btn.closest('.language-dropdown')) {
                existingBtn = btn;
            }
        });

        if (existingBtn) return;

        if (translations[lang]) {
            const newButton = document.createElement('button');
            newButton.setAttribute('data-lang', lang);
            newButton.textContent = getLanguageLabel(lang);
            newButton.setAttribute('title', getLanguageNativeName(lang));
            newButton.classList.add('dynamic-lang-btn');
            // Global listener handles click
            
            if (globalBtnMore && switcher.contains(globalBtnMore)) {
                switcher.insertBefore(newButton, globalBtnMore);
            } else {
                switcher.appendChild(newButton);
            }
        }
    });
}

function populateLanguageDropdown() {
    const dropdown = document.getElementById('languageDropdown');
    if (!dropdown) return;

    const availableLanguages = Object.keys(translations).filter(lang => !FIXED_LANGUAGES.includes(lang));
    
    availableLanguages.sort((a, b) => {
        const labelA = getLanguageLabel(a);
        const labelB = getLanguageLabel(b);
        return labelA.localeCompare(labelB);
    });

    dropdown.innerHTML = '';

    availableLanguages.forEach(lang => {
        const btn = document.createElement('button');
        const label = getLanguageLabel(lang);
        btn.textContent = label;
        btn.setAttribute('data-lang', lang);
        btn.setAttribute('title', getLanguageNativeName(lang));

        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            
            // Önceki dinamik butonları sil
            const allDynamicButtons = document.querySelectorAll('.dynamic-lang-btn');
            allDynamicButtons.forEach(btn => btn.remove());

            // Dili değiştir (Global fonksiyon localization.js'de)
            if (typeof setLanguage === 'function') setLanguage(lang);

            // Yeni butonu ekle
            ensureLanguageButtonExists(lang);

            dropdown.classList.remove('show');
        });

        dropdown.appendChild(btn);
    });
}

function initializeLanguageButtons() {
    populateLanguageDropdown();
    
    const btnMore = document.getElementById('btnMoreLanguages');
    const dropdown = document.getElementById('languageDropdown');

    if (btnMore && dropdown) {
        btnMore.addEventListener('click', (e) => {
            e.stopPropagation();
            dropdown.classList.toggle('show');
        });

        document.addEventListener('click', (e) => {
            if (!dropdown.contains(e.target) && e.target !== btnMore) {
                dropdown.classList.remove('show');
            }
        });
    }
}